// Augments the Env interface generated by `wrangler types` in
// worker-configuration.d.ts. Kept in a separate file deliberately: that file is
// regenerated wholesale by Wrangler, so anything added directly to it is lost
// on the next `npm run cf-typegen`.
//
// Email goes out through the Cloudflare Email Service `EMAIL` binding in
// wrangler.json. EMAIL_FROM is a plain var there; it must use one of the
// binding's allowed sender addresses (see ALLOWED_SENDERS in src/lib/email.ts).

declare namespace Cloudflare {
	interface Env {
		EMAIL_FROM?: string;
		// Jobs membership (src/lib/jobsAccess.ts). Both unset = /jobs stays fully open.
		JOBS_MEMBERSHIP_URL?: string;
		JOBS_MEMBERSHIP_PRICE?: string;
		// Free-tier LLM keys for /api/ai (src/lib/freeLlm.ts). Set as Cloudflare secrets, never as vars.
		GROQ_API_KEY?: string;
		GEMINI_API_KEY?: string;
		XAI_API_KEY?: string;
		// Telegram bot (src/lib/telegram.ts). Secrets; all unset = bot off.
		TELEGRAM_BOT_TOKEN?: string;
		TELEGRAM_OWNER_CHAT_ID?: string;
		TELEGRAM_CHANNEL_ID?: string;
	}
}
